# ==============================================================================# 056_EXECUTION_QUEUE.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")# ==============================================================================# EXECUTION QUEUE# ==============================================================================cur.execute("""CREATE TABLE IF NOT EXISTS execution_queue(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    module_name TEXT,    module_file TEXT,    priority TEXT,    action TEXT,    status TEXT,    started_at TEXT,    finished_at TEXT)""")conn.commit()# ==============================================================================# CARREGA AÃ‡Ã•ES DO ORQUESTRADOR# ==============================================================================cur.execute("""SELECTcomponent,priority,actionFROM orchestratorWHERE status='EXECUTED'ORDER BY id""")actions = cur.fetchall()created = 0for action in actions:    component = action["component"]    # --------------------------------------------------------------------------    # Resolve o mÃ³dulo responsÃ¡vel    # --------------------------------------------------------------------------    if component == "RESOURCE_MANAGER":        lookup = "RESOURCE_MANAGER"    elif component == "MONITOR_SCHEDULER":        lookup = "SCHEDULER_ENGINE"    elif component == "SYSTEM_READY":        lookup = "MASTER_CONTROL"    elif component == "KEEP_SYSTEM_RUNNING":        lookup = "MASTER_CONTROL"    else:        lookup = component    cur.execute("""    SELECT    module_name,    module_file    FROM module_registry    WHERE module_name=?    """,(lookup,))    module = cur.fetchone()    if module is None:        continue    cur.execute("""    INSERT INTO execution_queue(        created_at,        module_name,        module_file,        priority,        action,        status,        started_at,        finished_at    )    VALUES(?,?,?,?,?,?,?,?)    """,(        datetime.now().isoformat(),        module["module_name"],        module["module_file"],        action["priority"],        action["action"],        "WAITING",        None,        None    ))    created += 1conn.commit()# ==============================================================================# DASHBOARD# ==============================================================================print("="*80)print("EXECUTION QUEUE")print("="*80)cur.execute("""SELECTmodule_name,priority,action,statusFROM execution_queueORDER BYCASE priorityWHEN 'CRITICAL' THEN 1WHEN 'HIGH' THEN 2WHEN 'NORMAL' THEN 3WHEN 'LOW' THEN 4END,id""")rows = cur.fetchall()for row in rows:    print(        f"{row['priority']:<10}"        f"{row['module_name']:<25}"        f"{row['action']:<30}"        f"{row['status']}"    )print("="*80)print("ITENS NA FILA:", len(rows))print("="*80)conn.close()

